// Shared config + locators for the OPT-IN pair-NDA tests (spec: .qa/e2e/specs/hunter-nda.md §1).
import { expect, Page, Locator } from '@playwright/test';

export const PAIR = {
  enabled: process.env.QA_PAIR_NDA === '1',
  a: process.env.QA_PAIR_NDA_A || 'hunter_plus',
  b: process.env.QA_PAIR_NDA_B || 'hunter_free_2',
  aName: process.env.QA_PAIR_NDA_A_NAME || 'נועם כהן',
  bName: process.env.QA_PAIR_NDA_B_NAME || 'הד האנטר דמו 3',
  chat: process.env.QA_PAIR_NDA_CHAT || '9339566b-8799-41ce-b222-8c586a4afcce',
  job: process.env.QA_PAIR_NDA_JOB || '',
  candidate: process.env.QA_PAIR_NDA_CANDIDATE || '',
};

export const SKIP_MSG =
  'OPT-IN: needs a pair of headhunters WITHOUT an NDA in force (none on the stand since 07.11.2026). ' +
  'Run alone: QA_PAIR_NDA=1 [QA_PAIR_NDA_A/B, _A_NAME/_B_NAME, _CHAT, _JOB, _CANDIDATE] ' +
  'npx playwright test tests/hunter-nda/pair-refusal --project=tests --workers=1 — see specs/hunter-nda.md';

export const composer = (p: Page): Locator => p.getByPlaceholder('כתיבת הודעה');
export const sendBtn = (p: Page): Locator => p.getByRole('button', { name: 'שליחה', exact: true });

export const aWaitingBar = (p: Page) => p.getByText(`ממתינים לאישור של ${PAIR.bName} ל-NDA`);
export const aRefusedBar = (p: Page) => p.getByText(`${PAIR.bName} סירבו לאשר את ה-NDA, ולכן הפנייה לא נשלחה`);
export const bRequestBar = (p: Page) => p.getByText(`${PAIR.aName} פנו אליכם`);
export const bRefusedBar = (p: Page) => p.getByText(`סירבתם לאשר את ה-NDA עם ${PAIR.aName}`);

export async function openChat(p: Page) {
  await p.goto(`/messages?c=${PAIR.chat}`);
  await expect(composer(p)).toBeVisible({ timeout: 30_000 });
}

export async function expectComposerBlocked(p: Page, who: string) {
  await expect(composer(p), `${who}: «כתיבת הודעה» disabled (#fb0f43)`).toBeDisabled();
  await expect(sendBtn(p), `${who}: «שליחה» disabled (#fb0f43)`).toBeDisabled();
}

/** A: make sure a fresh NDA request is pending (re-request after a refusal). Skips when the pair NDA is in force. */
export async function ensurePending(a: Page) {
  await openChat(a);
  const state = await Promise.race([
    aRefusedBar(a).waitFor({ timeout: 15_000 }).then(() => 'refused'),
    aWaitingBar(a).waitFor({ timeout: 15_000 }).then(() => 'waiting'),
  ]).catch(() => 'none');
  if (state === 'none' && (await composer(a).isEnabled())) {
    return 'in-force' as const;
  }
  if (state === 'refused') {
    await a.getByRole('button', { name: 'שליחת בקשה חוזרת' }).click();
  }
  await expect(aWaitingBar(a)).toBeVisible({ timeout: 30_000 });
  return 'pending' as const;
}

/** B: refuse the pending request in the chat with A (never approve). */
export async function bRefuses(b: Page) {
  await openChat(b);
  await expect(bRequestBar(b)).toBeVisible({ timeout: 30_000 });
  await expect(b.getByRole('button', { name: 'אישור ה-NDA' })).toBeVisible();
  await expect(b.getByText('צפייה ב-NDA')).toBeVisible();
  await expectComposerBlocked(b, 'B before refusal');
  await b.getByRole('button', { name: 'סירוב', exact: true }).first().click();
  const confirm = b.getByRole('dialog').getByRole('button', { name: 'סירוב', exact: true });
  if (await confirm.isVisible().catch(() => false)) await confirm.click();
  await expect(bRequestBar(b)).toBeHidden({ timeout: 30_000 });
}

export async function bellText(p: Page): Promise<string> {
  await p.getByRole('button', { name: /^התראות/ }).first().click();
  const bell = p.getByRole('dialog', { name: 'התראות' });
  await expect(bell).toBeVisible();
  await expect(bell.getByText(PAIR.bName).first()).toBeVisible({ timeout: 30_000 });
  return (await bell.innerText()).replace(/[‎‏]/g, '');
}
